// 환경변수에서 채널별 노트북 생성 항목 파싱
// TOPIC_CHANNELS 형식: "IT Tech:채널A이름/UCaaaaa+채널B이름/UCbbbbb,맛집:UCzzzzzz"
// 채널당 독립 노트북 1개 생성, topic 키: "상위토픽::채널명"
const raw = $env.TOPIC_CHANNELS || '';
if (!raw.trim()) return [{ json: { skip: true, reason: 'TOPIC_CHANNELS 미설정' } }];

const today = new Date().toISOString().slice(0, 10);

const items = [];
for (const entry of raw.split(',')) {
  const colonIdx = entry.indexOf(':');
  if (colonIdx < 0) continue;
  const topicName = entry.slice(0, colonIdx).trim();
  const channelsPart = entry.slice(colonIdx + 1).trim();
  if (!topicName || !channelsPart) continue;
  for (const ch of channelsPart.split('+')) {
    const slashIdx = ch.indexOf('/');
    const channelName = slashIdx >= 0 ? ch.slice(0, slashIdx).trim() : '';
    const channelId   = slashIdx >= 0 ? ch.slice(slashIdx + 1).trim() : ch.trim();
    if (!channelId) continue;
    const topicKey = channelName ? `${topicName}::${channelName}` : topicName;
    const notebookName = channelName
      ? `${topicName} ${channelName} ${today}`
      : `${topicName} ${today}`;
    items.push({ topic: topicKey, channelIds: [channelId], notebookName });
  }
}

if (items.length === 0) return [{ json: { skip: true, reason: '파싱된 채널 없음' } }];
return items.map(t => ({ json: t }));

const result = $input.item.json;
const topic = $input.item.json.topic || '(unknown)';

if (result.status === 'success') {
  console.log(`[WF-10] ✅ 노트북 생성 완료: ${topic} → ${result.notebook_id} (${result.notebook_url})`);
} else {
  console.error(`[WF-10] ❌ 노트북 생성 실패: ${topic} — ${result.error}`);
}

return [{ json: result }];
